message.content:
{
  "scope_issues": [
    "The policy does not specify whether Gift Aid can be claimed on donations made in a single transaction or on a combination of donations from the same donor, nor whether a batch of donations from different sources must be treated separately."
  ],
  "statuses": [
    {
      "evidence_quote": "You can claim back 25p every time an individual donates £1 to your charity or community amateur sports club (CASC). This is called Gift Aid.",
      "id": "a1",
      "justification": "The policy states that Gift Aid applies to donations from individuals to charities or CASCs, and Elaine is an individual who donated to the charity, satisfying the condition that the donor is an individual.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "I run a small, independent charity which attempts to help people struggling with their vet costs. I have several people who pay monthly by direct debit and also receive some one off donations.",
      "id": "a2",
      "justification": "The charity is described as a small independent charity, and the donation is made to it, confirming that the donation is made to a charity, as required by E02 and E01.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "It did not go through a payroll giving scheme, and no shares, securities or other assets were delivered.",
      "id": "a3",
      "justification": "The donation was not made through Payroll Giving, as explicitly stated in the scenario, satisfying the condition that the donation is not made through Payroll Giving.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "The sales, booking and event records show nothing linked to this payment, and the only thing sent to Elaine was the standard thank-you email; she was not offered admission, advertising, a product or any other benefit.",
      "id": "a4",
      "justification": "The donation was not a payment for goods or services, nor was it made because the charity bought goods and services. The only response was a standard thank-you email, confirming no benefit was provided.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "she was not offered admission, advertising, a product or any other benefit",
      "id": "a5",
      "justification": "Elaine received no benefit beyond a standard thank-you email, and no benefit over a certain limit is indicated, satisfying the condition that the donor does not receive a benefit over a certain limit.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "It did not go through a payroll giving scheme, and no shares, securities or other assets were delivered.",
      "id": "a6",
      "justification": "The donation was not a payment of shares or other securities, as explicitly stated in the scenario, satisfying the condition that the donation is not a payment of shares or other securities.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "An older spreadsheet groups it with two CAF card and voucher redemptions (CC-0314, VC-0317), but those were paid to the charity in a combined batch on 18 March, while FP-0316-EL came directly from Elaine’s bank on 16 March. The treasurer wants to include this receipt in the ordinary Gift Aid return if the records permit.",
      "id": "a7",
      "justification": "The donation FP-0316-EL is directly from Elaine’s bank and is not from a charity card or voucher, even though it is grouped with CAF vouchers in a different batch. The evidence confirms it is not from a charity card or voucher, satisfying the proposition.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "Her tax summary for the year to 5 April 2026 shows £980 of Income Tax paid. Her signed note lists £200 of other Gift Aid donations that year; the treasurer’s sheet shows £30 recoverable on this £120 and £50 on the others, £80 in total, well below her £980.",
      "id": "a8",
      "justification": "Elaine paid £980 in Income Tax for the year, and the claimed Gift Aid on this donation is £30, which is less than or equal to her tax payment, satisfying the condition that the donor has paid at least as much in Income Tax or Capital Gains Tax as the amount claimed in Gift Aid.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "Elaine signed an electronic Gift Aid declaration on 15 March, and the e-signature service holds the signed document, timestamp and audit record. The declaration says it covers this donation, and the finance assistant matched it to FP-0316-EL through her donor record.",
      "id": "a9",
      "justification": "Elaine made a Gift Aid declaration that explicitly covers this donation, and it is linked to the transaction, satisfying the condition that the donor has made a Gift Aid declaration giving permission to claim Gift Aid.",
      "status": "TRUE"
    }
  ]
}
